CREATE TABLE "character_items" ( character_name TEXT NOT NULL, slot INTEGER NOT NULL, item_id INTEGER NOT NULL, count INTEGER NOT NULL, touch_effect_type INTEGER NOT NULL, touch_effect_value1 INTEGER NOT NULL, touch_effect_value2 INTEGER NOT NULL, touch_effect_value3 INTEGER NOT NULL, item_color INTEGER NOT NULL, spec_effect_value1 INTEGER NOT NULL, spec_effect_value2 INTEGER NOT NULL, spec_effect_value3 INTEGER NOT NULL, cur_durability INTEGER NOT NULL, custom_made INTEGER NOT NULL DEFAULT 0, prefix_type INTEGER NOT NULL DEFAULT 0, prefix_value INTEGER NOT NULL DEFAULT 0, secondary_type INTEGER NOT NULL DEFAULT 0, secondary_value INTEGER NOT NULL DEFAULT 0, enchant_bonus INTEGER NOT NULL DEFAULT 0, pos_x INTEGER NOT NULL, pos_y INTEGER NOT NULL, is_equipped INTEGER NOT NULL, PRIMARY KEY(character_name, slot), FOREIGN KEY(character_name) REFERENCES characters(character_name) ON DELETE CASCADE);
